  groupExit_leaveBlockedBody: '“{group}” ഗ്രൂപ്പിൽ നിങ്ങൾക്ക് ഇപ്പോഴും തുറന്ന ബാലൻസ് ഉണ്ട്. ഇപ്പോൾ വിട്ടാൽ മറ്റുള്ളവർക്ക് അത് സെറ്റിൽ ആകാതെ ശേഷിക്കും.',
