  groupExit_leaveBodyOne: 'നിങ്ങളുടെ ബാലൻസ് സെറ്റിൽ ആയി. ഗ്രൂപ്പ് ഈ ബ്രൗസറിൽ നിന്ന് പോകും, മറ്റേ അംഗത്തിന് നിങ്ങളുടെ ചെലവുകളിൽ നിങ്ങളുടെ പേര് നിലനിൽക്കും. തിരികെ വരാൻ, ആരെങ്കിലും നിങ്ങളെ വീണ്ടും ക്ഷണിക്കണം.',
  groupExit_leaveBodyOther: 'നിങ്ങളുടെ ബാലൻസ് സെറ്റിൽ ആയി. ഗ്രൂപ്പ് ഈ ബ്രൗസറിൽ നിന്ന് പോകും, മറ്റ് {count} അംഗങ്ങൾക്ക് നിങ്ങളുടെ ചെലവുകളിൽ നിങ്ങളുടെ പേര് നിലനിൽക്കും. തിരികെ വരാൻ, ആരെങ്കിലും നിങ്ങളെ വീണ്ടും ക്ഷണിക്കണം.',
  groupExit_leaveBodyAlone: 'നിങ്ങളുടെ ബാലൻസ് സെറ്റിൽ ആയി. ഗ്രൂപ്പിൽ മറ്റാരും ചേർന്നിട്ടില്ല, അതിനാൽ ഇത് എന്നെന്നേക്കുമായി ഡിലീറ്റ് ആകും.',
