  profile_signOutTitle: 'സൈൻ ഔട്ട് ചെയ്യണോ?',
  profile_signOutBody: 'എല്ലാം നിങ്ങളുടെ {provider} അക്കൗണ്ടുമായി സിങ്ക് ചെയ്തിട്ടുണ്ട്. നിങ്ങൾ സൈൻ ഔട്ട് ചെയ്യുമ്പോൾ, ഈ ബ്രൗസറിലെ പകർപ്പ് ഞങ്ങൾ മായ്ക്കും. നിങ്ങൾ വീണ്ടും സൈൻ ഇൻ ചെയ്യുമ്പോൾ ഗ്രൂപ്പുകൾ തിരികെ വരും.',
