  profile_signOutPendingTitleOther: '{count} മാറ്റങ്ങൾ ഇതുവരെ അപ്‌ലോഡ് ആയിട്ടില്ല',
  profile_signOutPendingBody: 'സിങ്ക് പൂർത്തിയാകുന്നത് വരെ നിങ്ങളുടെ ഡാറ്റ ഈ ബ്രൗസറിൽ ഇരിക്കും. എല്ലാം അപ്‌ലോഡ് ആയാൽ, ഞങ്ങൾ സൈൻ ഔട്ട് ചെയ്ത് ലോക്കൽ പകർപ്പ് മായ്ക്കും.',
  profile_signOutPendingBodyOffline: 'നിങ്ങൾ ഓഫ്‌ലൈനിലാണ്. സിങ്ക് പൂർത്തിയാകുന്നത് വരെ നിങ്ങളുടെ ഡാറ്റ ഈ ബ്രൗസറിൽ ഇരിക്കും. എല്ലാം അപ്‌ലോഡ് ആയാൽ, ഞങ്ങൾ സൈൻ ഔട്ട് ചെയ്ത് ലോക്കൽ പകർപ്പ് മായ്ക്കും.',
