  profile_eraseTitle: 'ഈ ബ്രൗസറിൽ നിന്ന് പ്രൊഫൈൽ മായ്ക്കണോ?',
  profile_eraseBody: 'നിങ്ങളുടെ അക്കൗണ്ടിന് Google അല്ലെങ്കിൽ Apple സൈൻ ഇൻ ഇല്ല. നിങ്ങൾ സൈൻ ഔട്ട് ചെയ്യുമ്പോൾ, ഈ ബ്രൗസറിലെ പകർപ്പ് ഞങ്ങൾ മായ്ക്കും. തിരികെ വരാൻ, നിങ്ങൾക്ക് റിക്കവറി കോഡ് വേണം. 30 ദിവസം ഉപയോഗിക്കാതിരുന്നാൽ, അക്കൗണ്ട് ഡിലീറ്റ് ആകുകയും കോഡ് പ്രവർത്തിക്കാതാകുകയും ചെയ്യും.',
  profile_eraseBodyNoCode: 'നിങ്ങൾ അക്കൗണ്ട് ഇല്ലാതെ ഉപയോഗിക്കുന്നു, ഇതുവരെ സിങ്ക് ചെയ്തിട്ടില്ല, അതിനാൽ റിക്കവറി കോഡ് ഇല്ല. നിങ്ങൾ പോകുമ്പോൾ, നിങ്ങളുടെ പ്രൊഫൈൽ എന്നെന്നേക്കുമായി ഇല്ലാതാകും.',
