  shareBill_anyone: 'ലിങ്ക് ഉള്ള ആർക്കും',
  shareBill_anyoneBody: 'സൈൻ ഇൻ ചെയ്യാതെ കാണാം. കമന്റ് ചെയ്യാൻ, ഗ്രൂപ്പിന് പുറത്തുള്ളവരാണെങ്കിലും ഒരു അക്കൗണ്ട് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യണം.',
  shareBill_note: 'ലിങ്ക് ചെലവ്, ആരാണ് പണം നൽകിയത്, ഓരോരുത്തരുടെയും വിഹിതം, അറ്റാച്ച്മെന്റുകൾ, കമന്റുകൾ എന്നിവ കാണിക്കുന്നു. ബാലൻസുകളും ഗ്രൂപ്പിന്റെ മറ്റ് ചെലവുകളും കാണിക്കില്ല.',
