  simplifyConflict_activity: 'ആക്റ്റിവിറ്റിയിൽ കാണുക',
  simplifyInfo_intro: 'ഒരു ഗ്രൂപ്പിൽ, ഓരോ ചെലവും രണ്ട് പേർക്കിടയിൽ കടങ്ങൾ ഉണ്ടാക്കുന്നു. കാലക്രമേണ, പണം വട്ടം കറങ്ങുന്നു. ലളിതമാക്കുന്നത് ആ കടങ്ങൾ ഒന്നിപ്പിച്ച് കുറച്ച് പേയ്‌മെന്റുകൾ നിർദ്ദേശിക്കുന്നു.',
  simplifyInfo_exampleTitle: 'ഒരു ഉദാഹരണം',
  simplifyInfo_example: 'Carla, Elisa-യ്ക്ക് {amount} നൽകാനുണ്ട്, Elisa, Bruno-യ്ക്ക് {amount} നൽകാനുണ്ട്.',
  simplifyInfo_before: 'മുമ്പ്',
  simplifyInfo_after: 'ലളിതമാക്കിയത്',
  simplifyInfo_beforeLabel: 'മുമ്പ്: Carla, Elisa-യ്ക്ക് {amount} നൽകുന്നു, Elisa, Bruno-യ്ക്ക് {amount} നൽകുന്നു. 2 പേയ്‌മെന്റുകൾ.',
  simplifyInfo_afterLabel: 'ലളിതമാക്കിയത്: Carla നേരിട്ട് Bruno-യ്ക്ക് {amount} നൽകുന്നു. Elisa ഒന്നും നൽകുന്നില്ല. 1 പേയ്‌മെന്റ്.',
  simplify_youCapital: 'നിങ്ങൾ',
  simplifyInfo_exampleResult: 'ലളിതമാക്കുമ്പോൾ, Carla നേരിട്ട് Bruno-യ്ക്ക് {amount} നൽകുന്നു, Elisa ഒന്നും നൽകുന്നില്ല.',
  simplifyInfo_totalTitle: 'ആകെ തുകകൾ മാറില്ല',
  simplifyInfo_totalText: 'ഗ്രൂപ്പിൽ {amount} നൽകാനുണ്ടായിരുന്നയാൾ ഇപ്പോഴും {amount} നൽകാനുണ്ട്. പണം എങ്ങോട്ട് പോകുന്നു എന്നത് മാത്രം മാറുന്നു.',
  simplifyInfo_strangerTitle: 'നിങ്ങൾ ഒരിക്കലും ചെലവ് വിഭജിക്കാത്ത ഒരാൾക്ക് നിങ്ങൾ പണം നൽകാനുണ്ടായേക്കാം',
  simplifyInfo_strangerText: 'അങ്ങനെ സംഭവിക്കുമ്പോൾ, ഗ്രൂപ്പിന്റെ ബാലൻസുകളിലെ ‘ലളിതമാക്കിയ കടങ്ങൾ’ എന്ന ലേബൽ നിങ്ങളെ അറിയിക്കും.',
  simplifyInfo_anyoneTitle: 'ആർക്കും ഇത് ഓണാക്കുകയോ ഓഫാക്കുകയോ ചെയ്യാം',
  simplifyInfo_anyoneText: '‘ഗ്രൂപ്പ് എഡിറ്റ് ചെയ്യുക’ എന്നതിൽ. ആരാണ് മാറ്റിയതെന്ന് ആക്റ്റിവിറ്റി കാണിക്കും, ഇനി മറ്റൊരാൾക്ക് നൽകുകയോ മറ്റൊരാളിൽ നിന്ന് സ്വീകരിക്കുകയോ ചെയ്യുന്നവർക്ക് അറിയിപ്പ് ലഭിക്കും.',
  simplifyInfo_offTitle: 'ഓഫാക്കിയാൽ പഴയതുപോലെയാകും',
  simplifyInfo_offText: 'പേയ്‌മെന്റുകൾ വീണ്ടും ഓരോ ചെലവും വിഭജിച്ചവർക്കിടയിലാകും. ഒരു ചെലവും രേഖപ്പെടുത്തിയ പേയ്‌മെന്റും മാറില്ല.',
  balances_simplifiedBody: '{count} പേയ്‌മെന്റുകൾ (മുമ്പ് {before}). നിങ്ങൾ ഒരിക്കലും ചെലവ് വിഭജിക്കാത്ത ഒരാൾക്ക് നൽകുകയോ അവരിൽ നിന്ന് സ്വീകരിക്കുകയോ ചെയ്തേക്കാം.',
  balances_simplifiedMinimal: 'ഇതിനകം ഏറ്റവും കുറഞ്ഞ പേയ്‌മെന്റുകൾ. അടുത്ത ചെലവുകൾ ലളിതമാക്കി വരും.',
  balances_simplifiedNote: 'ലളിതമാക്കിയ കടങ്ങളുള്ളപ്പോൾ, ആപ്പ് ഏറ്റവും കുറഞ്ഞ പേയ്‌മെന്റുകൾ നിർദ്ദേശിക്കുന്നു. “പണം ലഭിച്ചു”, “ഇതിനകം നൽകി” എന്നിവ ആപ്പിന് പുറത്ത് നടത്തിയ പേയ്‌മെന്റ് (Pix, ക്യാഷ്, ട്രാൻസ്ഫർ) രേഖപ്പെടുത്തുന്നു.',
  registerPayment_simplifiedNewPair: 'ലളിതമാക്കിയ കടം: {payer} പണം നൽകുന്നു, സ്വീകരിക്കുന്നത്: {receiver}. ഇത് മുമ്പ് ഇവർക്ക് നൽകാനുണ്ടായിരുന്നതാണ്: {insteadOf}.',
  registerPayment_simplifiedNewPairMe: 'ലളിതമാക്കിയ കടം: നിങ്ങൾ പണം നൽകുന്നു, സ്വീകരിക്കുന്നത്: {receiver}. ഇത് മുമ്പ് ഇവർക്ക് നൽകാനുണ്ടായിരുന്നതാണ്: {insteadOf}.',
  registerPayment_simplifiedNewPairToMe: 'ലളിതമാക്കിയ കടം: {payer} നിങ്ങൾക്ക് പണം നൽകുന്നു. ഇത് മുമ്പ് ഇവർക്ക് നൽകാനുണ്ടായിരുന്നതാണ്: {insteadOf}.',
