  simplifyChange_hint: 'നിങ്ങൾ ഇതിനകം പണം അയച്ചിട്ടുണ്ടെങ്കിൽ, എന്തായാലും പണം നൽകിയതായി അടയാളപ്പെടുത്തുക: ആപ്പ് കണക്ക് വീണ്ടും ചെയ്യും.',
